package org.aegis.android;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;

/** Real bounded SOCKS5 TCP gateway for the reviewed native TUN engine. No custom TCP/IP stack. */
final class NetworkGateway implements AutoCloseable {
    interface Connector{Socket connect(String host,byte[] address,int port)throws IOException;}
    final String user,password;private final Connector connector;private final DomainRules rules;private final ServerSocket listener;private final Set<Socket> sockets=ConcurrentHashMap.newKeySet();private final Semaphore flows=new Semaphore(12);private final ThreadPoolExecutor workers=new ThreadPoolExecutor(0,24,10,TimeUnit.SECONDS,new SynchronousQueue<>(),r->{Thread t=new Thread(r,"aegis-network-flow");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());private volatile boolean closed;final AtomicLong uploaded=new AtomicLong(),downloaded=new AtomicLong(),denied=new AtomicLong();
    NetworkGateway(DomainRules rules,Connector connector)throws IOException {this.rules=rules;this.connector=connector;byte[] random=new byte[32];new SecureRandom().nextBytes(random);password=Base64.getUrlEncoder().withoutPadding().encodeToString(random);Arrays.fill(random,(byte)0);user="aegis-local";listener=new ServerSocket();listener.bind(new InetSocketAddress(InetAddress.getByAddress(new byte[]{127,0,0,1}),0),12);Thread accept=new Thread(this::accept,"aegis-network-accept");accept.setDaemon(true);accept.start();}
    int port(){return listener.getLocalPort();}
    private void accept(){while(!closed)try{Socket client=listener.accept();client.setSoTimeout(10000);if(!flows.tryAcquire()){client.close();continue;}sockets.add(client);try{workers.execute(()->handle(client));}catch(RejectedExecutionException busy){flows.release();sockets.remove(client);client.close();}}catch(IOException stopped){if(!closed)close();}}
    private void handle(Socket client){Socket remote=null;try{DataInputStream in=new DataInputStream(client.getInputStream());OutputStream out=client.getOutputStream();if(in.readUnsignedByte()!=5)throw new IOException("SOCKS version");int count=in.readUnsignedByte();if(count<1||count>8)throw new IOException("SOCKS methods");boolean auth=false;for(int i=0;i<count;i++)if(in.readUnsignedByte()==2)auth=true;out.write(new byte[]{5,auth?(byte)2:(byte)255});out.flush();if(!auth)throw new IOException("SOCKS auth required");if(in.readUnsignedByte()!=1)throw new IOException("Auth version");byte[] who=new byte[in.readUnsignedByte()];in.readFully(who);byte[] secret=new byte[in.readUnsignedByte()];in.readFully(secret);boolean valid=MessageDigest.isEqual(who,user.getBytes(StandardCharsets.US_ASCII))&&MessageDigest.isEqual(secret,password.getBytes(StandardCharsets.US_ASCII));Arrays.fill(secret,(byte)0);out.write(new byte[]{1,valid?(byte)0:(byte)1});out.flush();if(!valid)throw new IOException("Local auth denied");if(in.readUnsignedByte()!=5||in.readUnsignedByte()!=1||in.readUnsignedByte()!=0)throw new IOException("TCP CONNECT only");int type=in.readUnsignedByte();String host=null;byte[] address=null;if(type==3){int size=in.readUnsignedByte();if(size<1||size>253)throw new IOException("Domain length");byte[] name=new byte[size];in.readFully(name);host=new String(name,StandardCharsets.US_ASCII);if(!rules.allowed(host))throw new IOException("Domain denied");host=DomainRules.domain(host);}else if(type==1||type==4){address=new byte[type==1?4:16];in.readFully(address);if(!DomainRules.publicAddress(InetAddress.getByAddress(address)))throw new IOException("Private destination denied");}else throw new IOException("SOCKS address");int port=in.readUnsignedShort();if(port<1)throw new IOException("Port");if(closed)throw new IOException("Stopped");remote=connector.connect(host,address,port);if(remote==null)throw new IOException("No connection");remote.setSoTimeout(120000);client.setSoTimeout(120000);sockets.add(remote);Socket target=remote;if(closed)throw new IOException("Stopped");out.write(new byte[]{5,0,0,1,0,0,0,0,0,0});out.flush();CountDownLatch reverse=new CountDownLatch(1);workers.execute(()->{try{copy(target,client,downloaded);}finally{reverse.countDown();}});copy(client,remote,uploaded);try{reverse.await(120,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}catch(Exception failure){denied.incrementAndGet();}finally{if(remote!=null){sockets.remove(remote);try{remote.close();}catch(IOException ignored){}}sockets.remove(client);try{client.close();}catch(IOException ignored){}flows.release();}}
    private void copy(Socket from,Socket to,AtomicLong counter){byte[] buffer=new byte[16384];try{InputStream in=from.getInputStream();OutputStream out=to.getOutputStream();for(int n;!closed&&(n=in.read(buffer))!=-1;){out.write(buffer,0,n);counter.addAndGet(n);}try{to.shutdownOutput();}catch(IOException ignored){}}catch(IOException stopped){}finally{Arrays.fill(buffer,(byte)0);}}
    public void close(){closed=true;try{listener.close();}catch(IOException ignored){}for(Socket s:sockets)try{s.close();}catch(IOException ignored){}sockets.clear();workers.shutdownNow();}
}
